@startuml

class EBike {
  + frameMaterial : string
  + batteryEnergy : double
  + controllerState : ControllerState
  + connectBattery()
  + disconnectBattery()
  + commandDriveSystem()
}

class Frame {
  + material : string
  + wheels : Wheel[]
}

class DriveSystem {
  + motor : Motor
}

class Battery {
  + energy : double
}

abstract class Controller {
  + state : ControllerState
  + controlBattery(battery : Battery)
  + commandDriveSystem()
}

class BasicController extends Controller {}

class AdvancedController extends Controller {
  + nextInspectionDate : date
}

class Wheel {}

class Motor {}

enum ControllerState {
  On
  Off
  Charging
}

EBike "1" *-- "1 frame" Frame
Frame "2" *-- "0..*" Wheel
EBike "0..1" -- "0..1 battery" Battery
EBike "1" --|> Controller

@enduml

